39	function getInitials(email?: string | null): string {
40	  if (!email) return "?";
41	  const name = email.split("@")[0];
42	  const parts = name.split(/[._-]/);
43	  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
44	  return name[0]?.toUpperCase() || "?";
45	}
46	
47	function getUserName(email?: string | null): string {
48	  if (!email) return "User";
49	  const name = email.split("@")[0];
50	  return name.replace(/[._-]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
51	}
