3	import { usePathname, useRouter } from "next/navigation";
4	import { useCallback, useMemo } from "react";
5	import { Briefcase, Building2, type LucideIcon } from "lucide-react";
6	
7	export type WorkspaceKey = "hiring" | "agency";
8	
9	export type Workspace = {
10	  key: WorkspaceKey;
11	  label: string;
12	  subtitle: string;
13	  icon: LucideIcon;
14	  /** Where clicking the workspace in the switcher navigates to. */
15	  homePath: string;
16	  /** Tailwind bg class for the tinted avatar square. */
17	  avatarBg: string;
18	  /** Tailwind text class that pairs with avatarBg. */
19	  avatarFg: string;
20	};
21	
22	export const WORKSPACES: Workspace[] = [
23	  {
24	    key: "hiring",
25	    label: "Hiring",
26	    subtitle: "Manage roles & candidates",
27	    icon: Briefcase,
28	    homePath: "/",
29	    avatarBg: "bg-blue-500/10",
30	    avatarFg: "text-blue-600",
31	  },
32	  {
33	    key: "agency",
34	    label: "Agency Hub",
35	    subtitle: "Clients, mandates & placements",
36	    icon: Building2,
37	    homePath: "/agency",
38	    avatarBg: "bg-purple-500/10",
39	    avatarFg: "text-purple-600",
40	  },
41	];
42	
43	/**
44	 * Derives the active workspace from the current pathname. Pages under
45	 * /agency belong to the Agency workspace; everything else belongs to
46	 * Hiring. Centralised here so the sidebar, header, and switcher stay
47	 * in sync without prop drilling.
48	 */
49	export function useWorkspace() {
50	  const pathname = usePathname() ?? "/";
51	  const router = useRouter();
52	
53	  const activeKey: WorkspaceKey = pathname.startsWith("/agency")
54	    ? "agency"
55	    : "hiring";
56	
57	  const active = useMemo<Workspace>(
58	    () => WORKSPACES.find((w) => w.key === activeKey) ?? WORKSPACES[0],
59	    [activeKey],
60	  );
61	
62	  const switchTo = useCallback(
63	    (key: WorkspaceKey) => {
64	      const target = WORKSPACES.find((w) => w.key === key);
65	      if (!target || target.key === activeKey) return;
66	      router.push(target.homePath);
67	    },
68	    [activeKey, router],
69	  );
70	
71	  return { active, activeKey, workspaces: WORKSPACES, switchTo };
72	}
