"use client";

import { Suspense, useMemo } from "react";
import Link from "next/link";
import { usePathname, useSearchParams } from "next/navigation";
import {
  Users,
  FileText,
  Award,
  Receipt,
  DollarSign,
  BarChart3,
  Globe,
  Layers,
} from "lucide-react";
import {
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuItem,
} from "@/components/ui/sidebar";
import { cn } from "@/lib/utils";
import { usePlatformConfig } from "@/hooks/usePlatformConfig";

/**
 * Sidebar shown when the user is inside the Agency workspace
 * (`/agency*`). Mirrors JobSidebar's layout exactly — brand, workspace
 * switcher, nav column — but swaps the Hiring nav items for Agency
 * sections (clients, mandates, placements, invoicing, commission,
 * analytics, portal).
 *
 * Each nav item links to /agency?section=<key>. The legacy AgencyHub
 * page already reads that URL param and swaps tab content, so we reuse
 * its state machine instead of re-implementing routing.
 */

type AgencyNavItem = {
  label: string;
  section: string;
  icon: React.ComponentType<{ className?: string }>;
};

const MAIN_NAV: AgencyNavItem[] = [
  { label: "Clients", section: "clients", icon: Users },
  { label: "Mandates", section: "mandates", icon: FileText },
  { label: "Placements", section: "placements", icon: Award },
  { label: "Invoicing", section: "invoicing", icon: Receipt },
  { label: "Commission", section: "commission", icon: DollarSign },
  { label: "Analytics", section: "analytics", icon: BarChart3 },
  { label: "Client Portal", section: "portal", icon: Globe },
];

const navLinkClass = (isActive: boolean) =>
  cn(
    "flex items-center gap-2.5 px-2 h-8 rounded-md text-[13px] font-medium transition-colors duration-100 w-full",
    "group-data-[collapsible=icon]:!size-9 group-data-[collapsible=icon]:!p-0 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:rounded-lg",
    isActive
      ? "bg-sidebar-accent text-sidebar-accent-foreground font-semibold"
      : "text-muted-foreground hover:text-foreground hover:bg-sidebar-accent/60",
  );

const iconClass = (isActive: boolean) =>
  cn("h-4 w-4 shrink-0", isActive ? "text-foreground" : "text-muted-foreground");

const AgencySidebarInner = () => {
  const { data: config } = usePlatformConfig();
  const appName = config?.app_name || "Rankora";
  const appLogo = config?.app_logo_url || null;

  const pathname = usePathname() ?? "/agency";
  const searchParams = useSearchParams();
  const currentSection = searchParams.get("section") ?? "clients";

  // Sidebar Settings / Feature Request are matched by pathname; Agency
  // nav items are matched by the ?section= param on /agency.
  const agencyNav = useMemo(
    () =>
      MAIN_NAV.map((item) => ({
        ...item,
        href: `/agency?section=${item.section}`,
        isActive: pathname === "/agency" && currentSection === item.section,
      })),
    [pathname, currentSection],
  );

  return (
    <Sidebar collapsible="icon" className="border-r-0">
      <SidebarHeader className="!flex !flex-row !gap-0 !p-0 h-14 mt-2 items-center px-2 group-data-[collapsible=icon]:px-2.5 group-data-[collapsible=icon]:justify-center">
        <div className="flex items-center gap-2.5 px-2 h-8 group-data-[collapsible=icon]:p-0 group-data-[collapsible=icon]:justify-center group-data-[collapsible=icon]:w-9">
          {appLogo ? (
            <img
              src={appLogo}
              alt={appName}
              className="h-4 w-4 shrink-0 object-contain"
            />
          ) : (
            <Layers className="h-4 w-4 text-primary shrink-0" />
          )}
          <span className="font-bold text-foreground tracking-tight text-[15px] group-data-[collapsible=icon]:hidden">
            {appName}
          </span>
        </div>
      </SidebarHeader>

      {/* Nav list — matches JobSidebar spacing (pt-4 pb-2). No section
          label: the workspace switcher in the header already conveys
          "you are in Agency". */}
      <SidebarContent className="px-2 pt-4 pb-2 group-data-[collapsible=icon]:px-2.5">
        <SidebarMenu>
          {agencyNav.map((item) => (
            <SidebarMenuItem key={item.section}>
              <Link
                href={item.href}
                prefetch
                className={navLinkClass(item.isActive)}
              >
                <item.icon className={iconClass(item.isActive)} />
                <span className="group-data-[collapsible=icon]:hidden">
                  {item.label}
                </span>
              </Link>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>

      </SidebarContent>
    </Sidebar>
  );
};

/**
 * Export wraps the inner in Suspense because useSearchParams requires
 * it in Next 16.
 */
const AgencySidebar = () => (
  <Suspense fallback={null}>
    <AgencySidebarInner />
  </Suspense>
);

export default AgencySidebar;

